288|/* TAG represents an open element.
289|   The name of the element is stored in both the document and API
290|   encodings.  The memory buffer 'buf' is a separately-allocated
291|   memory area which stores the name.  During the XML_Parse()/
292|   XMLParseBuffer() when the element is open, the memory for the 'raw'
293|   version of the name (in the document encoding) is shared with the
294|   document buffer.  If the element is open across calls to
295|   XML_Parse()/XML_ParseBuffer(), the buffer is re-allocated to
296|   contain the 'raw' name as well.
297|
298|   A parser reuses these structures, maintaining a list of allocated
299|   TAG objects in a free list.
300|*/
301|typedef struct tag {
302|  struct tag *parent;  /* parent of this element */
303|  const char *rawName; /* tagName in the original encoding */
304|  int rawNameLength;
305|  TAG_NAME name; /* tagName in the API encoding */
306|  char *buf;     /* buffer for name components */
307|  char *bufEnd;  /* end of the buffer */
308|  BINDING *bindings;
309|} TAG;
