774|/* Obtain entropy on Linux 3.17+ */
775|static int
776|writeRandomBytes_getrandom_nonblock(void *target, size_t count) {
777|  int success = 0; /* full count bytes written? */
778|  size_t bytesWrittenTotal = 0;
779|  const unsigned int getrandomFlags = GRND_NONBLOCK;
780|
781|  do {
782|    void *const currentTarget = (void *)((char *)target + bytesWrittenTotal);
783|    const size_t bytesToWrite = count - bytesWrittenTotal;
784|
785|    const int bytesWrittenMore =
786|#    if defined(HAVE_GETRANDOM)
787|        getrandom(currentTarget, bytesToWrite, getrandomFlags);
788|#    else
789|        syscall(SYS_getrandom, currentTarget, bytesToWrite, getrandomFlags);
790|#    endif
791|
792|    if (bytesWrittenMore > 0) {
793|      bytesWrittenTotal += bytesWrittenMore;
794|      if (bytesWrittenTotal >= count)
795|        success = 1;
796|    }
797|  } while (! success && (errno == EINTR));
798|
799|  return success;
