806|/* Extract entropy from /dev/urandom */
807|static int
808|writeRandomBytes_dev_urandom(void *target, size_t count) {
809|  int success = 0; /* full count bytes written? */
810|  size_t bytesWrittenTotal = 0;
811|
812|  const int fd = open("/dev/urandom", O_RDONLY);
813|  if (fd < 0) {
814|    return 0;
815|  }
816|
817|  do {
818|    void *const currentTarget = (void *)((char *)target + bytesWrittenTotal);
819|    const size_t bytesToWrite = count - bytesWrittenTotal;
820|
821|    const ssize_t bytesWrittenMore = read(fd, currentTarget, bytesToWrite);
822|
823|    if (bytesWrittenMore > 0) {
824|      bytesWrittenTotal += bytesWrittenMore;
825|      if (bytesWrittenTotal >= count)
826|        success = 1;
827|    }
828|  } while (! success && (errno == EINTR));
829|
830|  close(fd);
831|  return success;
832|}
