840|static void
841|writeRandomBytes_arc4random(void *target, size_t count) {
842|  size_t bytesWrittenTotal = 0;
843|
844|  while (bytesWrittenTotal < count) {
845|    const uint32_t random32 = arc4random();
846|    size_t i = 0;
847|
848|    for (; (i < sizeof(random32)) && (bytesWrittenTotal < count);
849|         i++, bytesWrittenTotal++) {
850|      const uint8_t random8 = (uint8_t)(random32 >> (i * 8));
851|      ((uint8_t *)target)[bytesWrittenTotal] = random8;
852|    }
853|  }
854|}
