860|/* Provide declaration of rand_s() for MinGW-32 (not 64, which has it),
861|   as it didn't declare it in its header prior to version 5.3.0 of its
862|   runtime package (mingwrt, containing stdlib.h).  The upstream fix
863|   was introduced at https://osdn.net/projects/mingw/ticket/39658 . */
864|#  if defined(__MINGW32__) && defined(__MINGW32_VERSION)                       \
865|      && __MINGW32_VERSION < 5003000L && ! defined(__MINGW64_VERSION_MAJOR)
866|__declspec(dllimport) int rand_s(unsigned int *);
