869|/* Obtain entropy on Windows using the rand_s() function which
870| * generates cryptographically secure random numbers.  Internally it
871| * uses RtlGenRandom API which is present in Windows XP and later.
872| */
873|static int
874|writeRandomBytes_rand_s(void *target, size_t count) {
875|  size_t bytesWrittenTotal = 0;
876|
877|  while (bytesWrittenTotal < count) {
878|    unsigned int random32 = 0;
879|    size_t i = 0;
880|
881|    if (rand_s(&random32))
882|      return 0; /* failure */
883|
884|    for (; (i < sizeof(random32)) && (bytesWrittenTotal < count);
885|         i++, bytesWrittenTotal++) {
886|      const uint8_t random8 = (uint8_t)(random32 >> (i * 8));
887|      ((uint8_t *)target)[bytesWrittenTotal] = random8;
888|    }
889|  }
890|  return 1; /* success */
891|}
