898|gather_time_entropy(void) {
899|#  ifdef _WIN32
900|  FILETIME ft;
901|  GetSystemTimeAsFileTime(&ft); /* never fails */
902|  return ft.dwHighDateTime ^ ft.dwLowDateTime;
903|#  else
904|  struct timeval tv;
905|  int gettimeofday_res;
906|
907|  gettimeofday_res = gettimeofday(&tv, NULL);
908|
909|#    if defined(NDEBUG)
910|  (void)gettimeofday_res;
911|#    else
912|  assert(gettimeofday_res == 0);
913|#    endif /* defined(NDEBUG) */
914|
915|  /* Microseconds time is <20 bits entropy */
916|  return tv.tv_usec;
917|#  endif
