2595|/* Initially tag->rawName always points into the parse buffer;
2596|   for those TAG instances opened while the current parse buffer was
2597|   processed, and not yet closed, we need to store tag->rawName in a more
2598|   permanent location, since the parse buffer is about to be discarded.
2599|*/
2600|static XML_Bool
2601|storeRawNames(XML_Parser parser) {
2602|  TAG *tag = parser->m_tagStack;
2603|  while (tag) {
2604|    int bufSize;
2605|    int nameLen = sizeof(XML_Char) * (tag->name.strLen + 1);
2606|    size_t rawNameLen;
2607|    char *rawNameBuf = tag->buf + nameLen;
2608|    /* Stop if already stored.  Since m_tagStack is a stack, we can stop
2609|       at the first entry that has already been copied; everything
2610|       below it in the stack is already been accounted for in a
2611|       previous call to this function.
2612|    */
2613|    if (tag->rawName == rawNameBuf)
2614|      break;
2615|    /* For reuse purposes we need to ensure that the
2616|       size of tag->buf is a multiple of sizeof(XML_Char).
2617|    */
2618|    rawNameLen = ROUND_UP(tag->rawNameLength, sizeof(XML_Char));
2619|    /* Detect and prevent integer overflow. */
2620|    if (rawNameLen > (size_t)INT_MAX - nameLen)
2621|      return XML_FALSE;
2622|    bufSize = nameLen + (int)rawNameLen;
2623|    if (bufSize > tag->bufEnd - tag->buf) {
2624|      char *temp = (char *)REALLOC(parser, tag->buf, bufSize);
2625|      if (temp == NULL)
2626|        return XML_FALSE;
2627|      /* if tag->name.str points to tag->buf (only when namespace
2628|         processing is off) then we have to update it
2629|      */
2630|      if (tag->name.str == (XML_Char *)tag->buf)
2631|        tag->name.str = (XML_Char *)temp;
2632|      /* if tag->name.localPart is set (when namespace processing is on)
2633|         then update it as well, since it will always point into tag->buf
2634|      */
2635|      if (tag->name.localPart)
2636|        tag->name.localPart
2637|            = (XML_Char *)temp + (tag->name.localPart - (XML_Char *)tag->buf);
2638|      tag->buf = temp;
2639|      tag->bufEnd = temp + bufSize;
2640|      rawNameBuf = temp + nameLen;
2641|    }
2642|    memcpy(rawNameBuf, tag->rawName, tag->rawNameLength);
2643|    tag->rawName = rawNameBuf;
2644|    tag = tag->parent;
2645|  }
2646|  return XML_TRUE;
2647|}
