2672|static enum XML_Error PTRCALL
2673|externalEntityInitProcessor2(XML_Parser parser, const char *start,
2674|                             const char *end, const char **endPtr) {
2675|  const char *next = start; /* XmlContentTok doesn't always set the last arg */
2676|  int tok = XmlContentTok(parser->m_encoding, start, end, &next);
2677|  switch (tok) {
2678|  case XML_TOK_BOM:
2679|#if XML_GE == 1
2680|    if (! accountingDiffTolerated(parser, tok, start, next, __LINE__,
2681|                                  XML_ACCOUNT_DIRECT)) {
2682|      accountingOnAbort(parser);
2683|      return XML_ERROR_AMPLIFICATION_LIMIT_BREACH;
2684|    }
2685|#endif /* XML_GE == 1 */
2686|
2687|    /* If we are at the end of the buffer, this would cause the next stage,
2688|       i.e. externalEntityInitProcessor3, to pass control directly to
2689|       doContent (by detecting XML_TOK_NONE) without processing any xml text
2690|       declaration - causing the error XML_ERROR_MISPLACED_XML_PI in doContent.
2691|    */
2692|    if (next == end && ! parser->m_parsingStatus.finalBuffer) {
2693|      *endPtr = next;
2694|      return XML_ERROR_NONE;
2695|    }
2696|    start = next;
2697|    break;
2698|  case XML_TOK_PARTIAL:
2699|    if (! parser->m_parsingStatus.finalBuffer) {
2700|      *endPtr = start;
2701|      return XML_ERROR_NONE;
2702|    }
2703|    parser->m_eventPtr = start;
2704|    return XML_ERROR_UNCLOSED_TOKEN;
2705|  case XML_TOK_PARTIAL_CHAR:
2706|    if (! parser->m_parsingStatus.finalBuffer) {
2707|      *endPtr = start;
2708|      return XML_ERROR_NONE;
2709|    }
2710|    parser->m_eventPtr = start;
2711|    return XML_ERROR_PARTIAL_CHAR;
2712|  }
2713|  parser->m_processor = externalEntityInitProcessor3;
2714|  return externalEntityInitProcessor3(parser, start, end, endPtr);
