2717|static enum XML_Error PTRCALL
2718|externalEntityInitProcessor3(XML_Parser parser, const char *start,
2719|                             const char *end, const char **endPtr) {
2720|  int tok;
2721|  const char *next = start; /* XmlContentTok doesn't always set the last arg */
2722|  parser->m_eventPtr = start;
2723|  tok = XmlContentTok(parser->m_encoding, start, end, &next);
2724|  /* Note: These bytes are accounted later in:
2725|           - processXmlDecl
2726|           - externalEntityContentProcessor
2727|  */
2728|  parser->m_eventEndPtr = next;
2729|
2730|  switch (tok) {
2731|  case XML_TOK_XML_DECL: {
2732|    enum XML_Error result;
2733|    result = processXmlDecl(parser, 1, start, next);
2734|    if (result != XML_ERROR_NONE)
2735|      return result;
2736|    switch (parser->m_parsingStatus.parsing) {
2737|    case XML_SUSPENDED:
2738|      *endPtr = next;
2739|      return XML_ERROR_NONE;
2740|    case XML_FINISHED:
2741|      return XML_ERROR_ABORTED;
2742|    default:
2743|      start = next;
2744|    }
2745|  } break;
2746|  case XML_TOK_PARTIAL:
2747|    if (! parser->m_parsingStatus.finalBuffer) {
2748|      *endPtr = start;
2749|      return XML_ERROR_NONE;
2750|    }
2751|    return XML_ERROR_UNCLOSED_TOKEN;
2752|  case XML_TOK_PARTIAL_CHAR:
2753|    if (! parser->m_parsingStatus.finalBuffer) {
2754|      *endPtr = start;
2755|      return XML_ERROR_NONE;
2756|    }
2757|    return XML_ERROR_PARTIAL_CHAR;
2758|  }
2759|  parser->m_processor = externalEntityContentProcessor;
2760|  parser->m_tagLevel = 1;
