6731|  while (*context != XML_T('\0')) {
6732|    if (*s == CONTEXT_SEP || *s == XML_T('\0')) {
6733|      ENTITY *e;
6734|      if (! poolAppendChar(&parser->m_tempPool, XML_T('\0')))
6735|        return XML_FALSE;
