6740|      if (*s != XML_T('\0'))
6741|        s++;
6742|      context = s;
6743|      poolDiscard(&parser->m_tempPool);
6744|    } else if (*s == XML_T(ASCII_EQUALS)) {
6745|      PREFIX *prefix;
6746|      if (poolLength(&parser->m_tempPool) == 0)
6747|        prefix = &dtd->defaultPrefix;
