6758|          if (! prefix->name)
6759|            return XML_FALSE;
6760|        }
6761|        poolDiscard(&parser->m_tempPool);
6762|      }
6763|      for (context = s + 1; *context != CONTEXT_SEP && *context != XML_T('\0');
6764|           context++)
6765|        if (! poolAppendChar(&parser->m_tempPool, *context))
6766|          return XML_FALSE;
6767|      if (! poolAppendChar(&parser->m_tempPool, XML_T('\0')))
6768|        return XML_FALSE;
