7390|  ** Detect overflow, avoiding _signed_ overflow undefined behavior
7391|  ** For a + b * c we check b * c in isolation first, so that addition of a
7392|  ** on top has no chance of making us accept a small non-negative number
7393|  */
7394|  const size_t stretch = sizeof(XML_Char); /* can be 4 bytes */
7395|
7396|  if (blockSize <= 0)
7397|    return 0;
7398|
7399|  if (blockSize > (int)(INT_MAX / stretch))
7400|    return 0;
7401|
7402|  {
7403|    const int stretchedBlockSize = blockSize * (int)stretch;
7404|    const int bytesToAllocate
7405|        = (int)(offsetof(BLOCK, s) + (unsigned)stretchedBlockSize);
7406|    if (bytesToAllocate < 0)
7407|      return 0;
7408|
7409|    return (size_t)bytesToAllocate;
