7424|    }
7425|    if (pool->end - pool->start < pool->freeBlocks->size) {
7426|      BLOCK *tem = pool->freeBlocks->next;
7427|      pool->freeBlocks->next = pool->blocks;
7428|      pool->blocks = pool->freeBlocks;
7429|      pool->freeBlocks = tem;
