7431|             (pool->end - pool->start) * sizeof(XML_Char));
7432|      pool->ptr = pool->blocks->s + (pool->ptr - pool->start);
7433|      pool->start = pool->blocks->s;
7434|      pool->end = pool->start + pool->blocks->size;
