7461|    temp = (BLOCK *)pool->mem->realloc_fcn(pool->blocks,
7462|                                           (unsigned)bytesToAllocate);
7463|    if (temp == NULL)
7464|      return XML_FALSE;
7465|    pool->blocks = temp;
7466|    pool->blocks->size = blockSize;
7467|    pool->ptr = pool->blocks->s + offsetInsideBlock;
7468|    pool->start = pool->blocks->s;
7469|    pool->end = pool->start + blockSize;
7470|  } else {
7471|    BLOCK *tem;
7472|    int blockSize = (int)(pool->end - pool->start);
7473|    size_t bytesToAllocate;
7474|
7475|    if (blockSize < 0) {
7476|      /* This condition traps a situation where either more than
7477|       * INT_MAX bytes have already been allocated (which is prevented
7478|       * by various pieces of program logic, not least this one, never
7479|       * mind the unlikelihood of actually having that much memory) or
7480|       * the pool control fields have been corrupted (which could
7481|       * conceivably happen in an extremely buggy user handler
7482|       * function).  Either way it isn't readily testable, so we
7483|       * exclude it from the coverage statistics.
