7506|    tem->next = pool->blocks;
7507|    pool->blocks = tem;
7508|    if (pool->ptr != pool->start)
7509|      memcpy(tem->s, pool->start, (pool->ptr - pool->start) * sizeof(XML_Char));
7510|    pool->ptr = tem->s + (pool->ptr - pool->start);
