7578|static XML_Content *
7579|build_model(XML_Parser parser) {
7580|  /* Function build_model transforms the existing parser->m_dtd->scaffold
7581|   * array of CONTENT_SCAFFOLD tree nodes into a new array of
7582|   * XML_Content tree nodes followed by a gapless list of zero-terminated
7583|   * strings. */
7584|  DTD *const dtd = parser->m_dtd; /* save one level of indirection */
7585|  XML_Content *ret;
7586|  XML_Char *str; /* the current string writing location */
7587|
7588|  /* Detect and prevent integer overflow.
7589|   * The preprocessor guard addresses the "always false" warning
7590|   * from -Wtype-limits on platforms where
7591|   * sizeof(unsigned int) < sizeof(size_t), e.g. on x86_64. */
7592|#if UINT_MAX >= SIZE_MAX
7593|  if (dtd->scaffCount > (size_t)(-1) / sizeof(XML_Content)) {
7594|    return NULL;
7595|  }
7596|  if (dtd->contentStringLen > (size_t)(-1) / sizeof(XML_Char)) {
7597|    return NULL;
7598|  }
7599|#endif
7600|  if (dtd->scaffCount * sizeof(XML_Content)
7601|      > (size_t)(-1) - dtd->contentStringLen * sizeof(XML_Char)) {
7602|    return NULL;
7603|  }
7604|
7605|  const size_t allocsize = (dtd->scaffCount * sizeof(XML_Content)
7606|                            + (dtd->contentStringLen * sizeof(XML_Char)));
7607|
7608|  ret = (XML_Content *)MALLOC(parser, allocsize);
7609|  if (! ret)
7610|    return NULL;
7611|
7612|  /* What follows is an iterative implementation (of what was previously done
7613|   * recursively in a dedicated function called "build_node".  The old recursive
7614|   * build_node could be forced into stack exhaustion from input as small as a
7615|   * few megabyte, and so that was a security issue.  Hence, a function call
7616|   * stack is avoided now by resolving recursion.)
7617|   *
7618|   * The iterative approach works as follows:
7619|   *
7620|   * - We have two writing pointers, both walking up the result array; one does
7621|   *   the work, the other creates "jobs" for its colleague to do, and leads
7622|   *   the way:
7623|   *
7624|   *   - The faster one, pointer jobDest, always leads and writes "what job
7625|   *     to do" by the other, once they reach that place in the
7626|   *     array: leader "jobDest" stores the source node array index (relative
7627|   *     to array dtd->scaffold) in field "numchildren".
7628|   *
7629|   *   - The slower one, pointer dest, looks at the value stored in the
7630|   *     "numchildren" field (which actually holds a source node array index
7631|   *     at that time) and puts the real data from dtd->scaffold in.
7632|   *
7633|   * - Before the loop starts, jobDest writes source array index 0
7634|   *   (where the root node is located) so that dest will have something to do
7635|   *   when it starts operation.
7636|   *
7637|   * - Whenever nodes with children are encountered, jobDest appends
7638|   *   them as new jobs, in order.  As a result, tree node siblings are
7639|   *   adjacent in the resulting array, for example:
7640|   *
7641|   *     [0] root, has two children
7642|   *       [1] first child of 0, has three children
7643|   *         [3] first child of 1, does not have children
7644|   *         [4] second child of 1, does not have children
7645|   *         [5] third child of 1, does not have children
7646|   *       [2] second child of 0, does not have children
7647|   *
7648|   *   Or (the same data) presented in flat array view:
7649|   *
7650|   *     [0] root, has two children
7651|   *
7652|   *     [1] first child of 0, has three children
7653|   *     [2] second child of 0, does not have children
7654|   *
7655|   *     [3] first child of 1, does not have children
7656|   *     [4] second child of 1, does not have children
7657|   *     [5] third child of 1, does not have children
7658|   *
7659|   * - The algorithm repeats until all target array indices have been processed.
7660|   */
7661|  XML_Content *dest = ret; /* tree node writing location, moves upwards */
7662|  XML_Content *const destLimit = &ret[dtd->scaffCount];
7663|  XML_Content *jobDest = ret; /* next free writing location in target array */
7664|  str = (XML_Char *)&ret[dtd->scaffCount];
7665|
7666|  /* Add the starting job, the root node (index 0) of the source tree  */
7667|  (jobDest++)->numchildren = 0;
7668|
7669|  for (; dest < destLimit; dest++) {
7670|    /* Retrieve source tree array index from job storage */
7671|    const int src_node = (int)dest->numchildren;
7672|
7673|    /* Convert item */
7674|    dest->type = dtd->scaffold[src_node].type;
7675|    dest->quant = dtd->scaffold[src_node].quant;
7676|    if (dest->type == XML_CTYPE_NAME) {
7677|      const XML_Char *src;
7678|      dest->name = str;
7679|      src = dtd->scaffold[src_node].name;
7680|      for (;;) {
7681|        *str++ = *src;
7682|        if (! *src)
7683|          break;
7684|        src++;
7685|      }
7686|      dest->numchildren = 0;
7687|      dest->children = NULL;
7688|    } else {
7689|      unsigned int i;
7690|      int cn;
7691|      dest->name = NULL;
7692|      dest->numchildren = dtd->scaffold[src_node].childcnt;
7693|      dest->children = jobDest;
7694|
7695|      /* Append scaffold indices of children to array */
7696|      for (i = 0, cn = dtd->scaffold[src_node].firstchild;
7697|           i < dest->numchildren; i++, cn = dtd->scaffold[cn].nextsib)
7698|        (jobDest++)->numchildren = (unsigned int)cn;
7699|    }
7700|  }
7701|
7702|  return ret;
7703|}
