7728|static XML_Char *
7729|copyString(const XML_Char *s, const XML_Memory_Handling_Suite *memsuite) {
7730|  size_t charsRequired = 0;
7731|  XML_Char *result;
7732|
7733|  /* First determine how long the string is */
7734|  while (s[charsRequired] != 0) {
7735|    charsRequired++;
7736|  }
7737|  /* Include the terminator */
7738|  charsRequired++;
7739|
7740|  /* Now allocate space for the copy */
7741|  result = memsuite->malloc_fcn(charsRequired * sizeof(XML_Char));
7742|  if (result == NULL)
7743|    return NULL;
7744|  /* Copy the original into place */
7745|  memcpy(result, s, charsRequired * sizeof(XML_Char));
7746|  return result;
