7789|static void
7790|accountingReportDiff(XML_Parser rootParser,
7791|                     unsigned int levelsAwayFromRootParser, const char *before,
7792|                     const char *after, ptrdiff_t bytesMore, int source_line,
7793|                     enum XML_Account account) {
7794|  assert(! rootParser->m_parentParser);
7795|
7796|  fprintf(stderr,
7797|          " (+" EXPAT_FMT_PTRDIFF_T("6") " bytes %s|%d, xmlparse.c:%d) %*s\"",
7798|          bytesMore, (account == XML_ACCOUNT_DIRECT) ? "DIR" : "EXP",
7799|          levelsAwayFromRootParser, source_line, 10, "");
7800|
7801|  const char ellipis[] = "[..]";
7802|  const size_t ellipsisLength = sizeof(ellipis) /* because compile-time */ - 1;
7803|  const unsigned int contextLength = 10;
7804|
7805|  /* Note: Performance is of no concern here */
7806|  const char *walker = before;
7807|  if ((rootParser->m_accounting.debugLevel >= 3u)
7808|      || (after - before)
7809|             <= (ptrdiff_t)(contextLength + ellipsisLength + contextLength)) {
7810|    for (; walker < after; walker++) {
7811|      fprintf(stderr, "%s", unsignedCharToPrintable(walker[0]));
7812|    }
7813|  } else {
7814|    for (; walker < before + contextLength; walker++) {
7815|      fprintf(stderr, "%s", unsignedCharToPrintable(walker[0]));
7816|    }
7817|    fprintf(stderr, ellipis);
7818|    walker = after - contextLength;
7819|    for (; walker < after; walker++) {
7820|      fprintf(stderr, "%s", unsignedCharToPrintable(walker[0]));
7821|    }
7822|  }
7823|  fprintf(stderr, "\"\n");
7824|}
