7826|static XML_Bool
7827|accountingDiffTolerated(XML_Parser originParser, int tok, const char *before,
7828|                        const char *after, int source_line,
7829|                        enum XML_Account account) {
7830|  /* Note: We need to check the token type *first* to be sure that
7831|   *       we can even access variable <after>, safely.
7832|   *       E.g. for XML_TOK_NONE <after> may hold an invalid pointer. */
7833|  switch (tok) {
7834|  case XML_TOK_INVALID:
7835|  case XML_TOK_PARTIAL:
7836|  case XML_TOK_PARTIAL_CHAR:
7837|  case XML_TOK_NONE:
7838|    return XML_TRUE;
7839|  }
7840|
7841|  if (account == XML_ACCOUNT_NONE)
7842|    return XML_TRUE; /* because these bytes have been accounted for, already */
7843|
7844|  unsigned int levelsAwayFromRootParser;
7845|  const XML_Parser rootParser
7846|      = getRootParserOf(originParser, &levelsAwayFromRootParser);
7847|  assert(! rootParser->m_parentParser);
7848|
7849|  const int isDirect
7850|      = (account == XML_ACCOUNT_DIRECT) && (originParser == rootParser);
7851|  const ptrdiff_t bytesMore = after - before;
7852|
7853|  XmlBigCount *const additionTarget
7854|      = isDirect ? &rootParser->m_accounting.countBytesDirect
7855|                 : &rootParser->m_accounting.countBytesIndirect;
7856|
7857|  /* Detect and avoid integer overflow */
7858|  if (*additionTarget > (XmlBigCount)(-1) - (XmlBigCount)bytesMore)
7859|    return XML_FALSE;
7860|  *additionTarget += bytesMore;
7861|
7862|  const XmlBigCount countBytesOutput
7863|      = rootParser->m_accounting.countBytesDirect
7864|        + rootParser->m_accounting.countBytesIndirect;
7865|  const float amplificationFactor
7866|      = accountingGetCurrentAmplification(rootParser);
7867|  const XML_Bool tolerated
7868|      = (countBytesOutput < rootParser->m_accounting.activationThresholdBytes)
7869|        || (amplificationFactor
7870|            <= rootParser->m_accounting.maximumAmplificationFactor);
7871|
7872|  if (rootParser->m_accounting.debugLevel >= 2u) {
7873|    accountingReportStats(rootParser, "");
7874|    accountingReportDiff(rootParser, levelsAwayFromRootParser, before, after,
7875|                         bytesMore, source_line, account);
7876|  }
7877|
7878|  return tolerated;
7879|}
