783|/* Obtain entropy on Linux 3.17+ */
784|static int
785|writeRandomBytes_getrandom_nonblock(void *target, size_t count) {
786|  int success = 0; /* full count bytes written? */
787|  size_t bytesWrittenTotal = 0;
788|  const unsigned int getrandomFlags = GRND_NONBLOCK;
789|
790|  do {
791|    void *const currentTarget = (void *)((char *)target + bytesWrittenTotal);
792|    const size_t bytesToWrite = count - bytesWrittenTotal;
793|
794|    const int bytesWrittenMore =
795|#    if defined(HAVE_GETRANDOM)
796|        getrandom(currentTarget, bytesToWrite, getrandomFlags);
797|#    else
798|        syscall(SYS_getrandom, currentTarget, bytesToWrite, getrandomFlags);
799|#    endif
800|
801|    if (bytesWrittenMore > 0) {
802|      bytesWrittenTotal += bytesWrittenMore;
803|      if (bytesWrittenTotal >= count)
804|        success = 1;
805|    }
806|  } while (! success && (errno == EINTR));
807|
808|  return success;
809|}
