815|/* Extract entropy from /dev/urandom */
816|static int
817|writeRandomBytes_dev_urandom(void *target, size_t count) {
818|  int success = 0; /* full count bytes written? */
819|  size_t bytesWrittenTotal = 0;
820|
821|  const int fd = open("/dev/urandom", O_RDONLY);
822|  if (fd < 0) {
823|    return 0;
824|  }
825|
826|  do {
827|    void *const currentTarget = (void *)((char *)target + bytesWrittenTotal);
828|    const size_t bytesToWrite = count - bytesWrittenTotal;
829|
830|    const ssize_t bytesWrittenMore = read(fd, currentTarget, bytesToWrite);
831|
832|    if (bytesWrittenMore > 0) {
833|      bytesWrittenTotal += bytesWrittenMore;
834|      if (bytesWrittenTotal >= count)
835|        success = 1;
836|    }
837|  } while (! success && (errno == EINTR));
838|
839|  close(fd);
840|  return success;
841|}
