849|static void
850|writeRandomBytes_arc4random(void *target, size_t count) {
851|  size_t bytesWrittenTotal = 0;
852|
853|  while (bytesWrittenTotal < count) {
854|    const uint32_t random32 = arc4random();
855|    size_t i = 0;
856|
857|    for (; (i < sizeof(random32)) && (bytesWrittenTotal < count);
858|         i++, bytesWrittenTotal++) {
859|      const uint8_t random8 = (uint8_t)(random32 >> (i * 8));
860|      ((uint8_t *)target)[bytesWrittenTotal] = random8;
861|    }
862|  }
863|}
