869|/* Provide declaration of rand_s() for MinGW-32 (not 64, which has it),
870|   as it didn't declare it in its header prior to version 5.3.0 of its
871|   runtime package (mingwrt, containing stdlib.h).  The upstream fix
872|   was introduced at https://osdn.net/projects/mingw/ticket/39658 . */
873|#  if defined(__MINGW32__) && defined(__MINGW32_VERSION)                       \
874|      && __MINGW32_VERSION < 5003000L && ! defined(__MINGW64_VERSION_MAJOR)
875|__declspec(dllimport) int rand_s(unsigned int *);
