878|/* Obtain entropy on Windows using the rand_s() function which
879| * generates cryptographically secure random numbers.  Internally it
880| * uses RtlGenRandom API which is present in Windows XP and later.
881| */
882|static int
883|writeRandomBytes_rand_s(void *target, size_t count) {
884|  size_t bytesWrittenTotal = 0;
885|
886|  while (bytesWrittenTotal < count) {
887|    unsigned int random32 = 0;
888|    size_t i = 0;
889|
890|    if (rand_s(&random32))
891|      return 0; /* failure */
892|
893|    for (; (i < sizeof(random32)) && (bytesWrittenTotal < count);
894|         i++, bytesWrittenTotal++) {
895|      const uint8_t random8 = (uint8_t)(random32 >> (i * 8));
896|      ((uint8_t *)target)[bytesWrittenTotal] = random8;
897|    }
898|  }
899|  return 1; /* success */
