915|
916|  gettimeofday_res = gettimeofday(&tv, NULL);
917|
918|#    if defined(NDEBUG)
919|  (void)gettimeofday_res;
920|#    else
921|  assert(gettimeofday_res == 0);
922|#    endif /* defined(NDEBUG) */
923|
924|  /* Microseconds time is <20 bits entropy */
925|  return tv.tv_usec;
