940|static unsigned long
941|generate_hash_secret_salt(XML_Parser parser) {
942|  unsigned long entropy;
943|  (void)parser;
944|
945|  /* "Failproof" high quality providers: */
946|#if defined(HAVE_ARC4RANDOM_BUF)
947|  arc4random_buf(&entropy, sizeof(entropy));
948|  return ENTROPY_DEBUG("arc4random_buf", entropy);
949|#elif defined(HAVE_ARC4RANDOM)
950|  writeRandomBytes_arc4random((void *)&entropy, sizeof(entropy));
951|  return ENTROPY_DEBUG("arc4random", entropy);
952|#else
953|  /* Try high quality providers first .. */
954|#  ifdef _WIN32
955|  if (writeRandomBytes_rand_s((void *)&entropy, sizeof(entropy))) {
956|    return ENTROPY_DEBUG("rand_s", entropy);
957|  }
958|#  elif defined(HAVE_GETRANDOM) || defined(HAVE_SYSCALL_GETRANDOM)
959|  if (writeRandomBytes_getrandom_nonblock((void *)&entropy, sizeof(entropy))) {
960|    return ENTROPY_DEBUG("getrandom", entropy);
961|  }
962|#  endif
963|#  if ! defined(_WIN32) && defined(XML_DEV_URANDOM)
964|  if (writeRandomBytes_dev_urandom((void *)&entropy, sizeof(entropy))) {
965|    return ENTROPY_DEBUG("/dev/urandom", entropy);
966|  }
967|#  endif /* ! defined(_WIN32) && defined(XML_DEV_URANDOM) */
968|  /* .. and self-made low quality for backup: */
969|
970|  /* Process ID is 0 bits entropy if attacker has local access */
971|  entropy = gather_time_entropy() ^ getpid();
972|
973|  /* Factors are 2^31-1 and 2^61-1 (Mersenne primes M31 and M61) */
974|  if (sizeof(unsigned long) == 4) {
975|    return ENTROPY_DEBUG("fallback(4)", entropy * 2147483647);
976|  } else {
977|    return ENTROPY_DEBUG("fallback(8)",
978|                         entropy * (unsigned long)2305843009213693951ULL);
979|  }
980|#endif
981|}
