2621|/* Initially tag->rawName always points into the parse buffer;
2622|   for those TAG instances opened while the current parse buffer was
2623|   processed, and not yet closed, we need to store tag->rawName in a more
2624|   permanent location, since the parse buffer is about to be discarded.
2625|*/
2626|static XML_Bool
2627|storeRawNames(XML_Parser parser) {
2628|  TAG *tag = parser->m_tagStack;
2629|  while (tag) {
2630|    int bufSize;
2631|    int nameLen = sizeof(XML_Char) * (tag->name.strLen + 1);
2632|    size_t rawNameLen;
2633|    char *rawNameBuf = tag->buf + nameLen;
2634|    /* Stop if already stored.  Since m_tagStack is a stack, we can stop
2635|       at the first entry that has already been copied; everything
2636|       below it in the stack is already been accounted for in a
2637|       previous call to this function.
2638|    */
2639|    if (tag->rawName == rawNameBuf)
2640|      break;
2641|    /* For reuse purposes we need to ensure that the
2642|       size of tag->buf is a multiple of sizeof(XML_Char).
2643|    */
2644|    rawNameLen = ROUND_UP(tag->rawNameLength, sizeof(XML_Char));
2645|    /* Detect and prevent integer overflow. */
2646|    if (rawNameLen > (size_t)INT_MAX - nameLen)
2647|      return XML_FALSE;
2648|    bufSize = nameLen + (int)rawNameLen;
2649|    if (bufSize > tag->bufEnd - tag->buf) {
2650|      char *temp = (char *)REALLOC(parser, tag->buf, bufSize);
2651|      if (temp == NULL)
2652|        return XML_FALSE;
2653|      /* if tag->name.str points to tag->buf (only when namespace
2654|         processing is off) then we have to update it
2655|      */
2656|      if (tag->name.str == (XML_Char *)tag->buf)
2657|        tag->name.str = (XML_Char *)temp;
2658|      /* if tag->name.localPart is set (when namespace processing is on)
2659|         then update it as well, since it will always point into tag->buf
2660|      */
2661|      if (tag->name.localPart)
2662|        tag->name.localPart
2663|            = (XML_Char *)temp + (tag->name.localPart - (XML_Char *)tag->buf);
2664|      tag->buf = temp;
2665|      tag->bufEnd = temp + bufSize;
2666|      rawNameBuf = temp + nameLen;
2667|    }
2668|    memcpy(rawNameBuf, tag->rawName, tag->rawNameLength);
2669|    tag->rawName = rawNameBuf;
2670|    tag = tag->parent;
2671|  }
2672|  return XML_TRUE;
2673|}
