5734|static enum XML_Error PTRCALL
5735|epilogProcessor(XML_Parser parser, const char *s, const char *end,
5736|                const char **nextPtr) {
5737|  parser->m_processor = epilogProcessor;
5738|  parser->m_eventPtr = s;
5739|  for (;;) {
5740|    const char *next = NULL;
5741|    int tok = XmlPrologTok(parser->m_encoding, s, end, &next);
5742|#if XML_GE == 1
5743|    if (! accountingDiffTolerated(parser, tok, s, next, __LINE__,
5744|                                  XML_ACCOUNT_DIRECT)) {
5745|      accountingOnAbort(parser);
5746|      return XML_ERROR_AMPLIFICATION_LIMIT_BREACH;
5747|    }
5748|#endif
5749|    parser->m_eventEndPtr = next;
5750|    switch (tok) {
5751|    /* report partial linebreak - it might be the last token */
5752|    case -XML_TOK_PROLOG_S:
5753|      if (parser->m_defaultHandler) {
5754|        reportDefault(parser, parser->m_encoding, s, next);
5755|        if (parser->m_parsingStatus.parsing == XML_FINISHED)
5756|          return XML_ERROR_ABORTED;
5757|      }
5758|      *nextPtr = next;
5759|      return XML_ERROR_NONE;
5760|    case XML_TOK_NONE:
5761|      *nextPtr = s;
5762|      return XML_ERROR_NONE;
5763|    case XML_TOK_PROLOG_S:
5764|      if (parser->m_defaultHandler)
5765|        reportDefault(parser, parser->m_encoding, s, next);
5766|      break;
5767|    case XML_TOK_PI:
5768|      if (! reportProcessingInstruction(parser, parser->m_encoding, s, next))
5769|        return XML_ERROR_NO_MEMORY;
5770|      break;
5771|    case XML_TOK_COMMENT:
5772|      if (! reportComment(parser, parser->m_encoding, s, next))
5773|        return XML_ERROR_NO_MEMORY;
5774|      break;
5775|    case XML_TOK_INVALID:
5776|      parser->m_eventPtr = next;
5777|      return XML_ERROR_INVALID_TOKEN;
5778|    case XML_TOK_PARTIAL:
5779|      if (! parser->m_parsingStatus.finalBuffer) {
5780|        *nextPtr = s;
5781|        return XML_ERROR_NONE;
5782|      }
5783|      return XML_ERROR_UNCLOSED_TOKEN;
5784|    case XML_TOK_PARTIAL_CHAR:
5785|      if (! parser->m_parsingStatus.finalBuffer) {
5786|        *nextPtr = s;
5787|        return XML_ERROR_NONE;
5788|      }
5789|      return XML_ERROR_PARTIAL_CHAR;
5790|    default:
5791|      return XML_ERROR_JUNK_AFTER_DOC_ELEMENT;
5792|    }
5793|    parser->m_eventPtr = s = next;
5794|    switch (parser->m_parsingStatus.parsing) {
5795|    case XML_SUSPENDED:
5796|      *nextPtr = next;
5797|      return XML_ERROR_NONE;
5798|    case XML_FINISHED:
5799|      return XML_ERROR_ABORTED;
5800|    default:;
5801|    }
5802|  }
