7160|static NAMED *
7161|lookup(XML_Parser parser, HASH_TABLE *table, KEY name, size_t createSize) {
7162|  size_t i;
7163|  if (table->size == 0) {
7164|    size_t tsize;
7165|    if (! createSize)
7166|      return NULL;
7167|    table->power = INIT_POWER;
7168|    /* table->size is a power of 2 */
7169|    table->size = (size_t)1 << INIT_POWER;
7170|    tsize = table->size * sizeof(NAMED *);
7171|    table->v = table->mem->malloc_fcn(tsize);
7172|    if (! table->v) {
7173|      table->size = 0;
7174|      return NULL;
7175|    }
7176|    memset(table->v, 0, tsize);
7177|    i = hash(parser, name) & ((unsigned long)table->size - 1);
7178|  } else {
7179|    unsigned long h = hash(parser, name);
7180|    unsigned long mask = (unsigned long)table->size - 1;
7181|    unsigned char step = 0;
7182|    i = h & mask;
7183|    while (table->v[i]) {
7184|      if (keyeq(name, table->v[i]->name))
7185|        return table->v[i];
7186|      if (! step)
7187|        step = PROBE_STEP(h, mask, table->power);
7188|      i < step ? (i += table->size - step) : (i -= step);
7189|    }
7190|    if (! createSize)
7191|      return NULL;
7192|
7193|    /* check for overflow (table is half full) */
7194|    if (table->used >> (table->power - 1)) {
7195|      unsigned char newPower = table->power + 1;
7196|
7197|      /* Detect and prevent invalid shift */
7198|      if (newPower >= sizeof(unsigned long) * 8 /* bits per byte */) {
7199|        return NULL;
7200|      }
7201|
7202|      size_t newSize = (size_t)1 << newPower;
7203|      unsigned long newMask = (unsigned long)newSize - 1;
7204|
7205|      /* Detect and prevent integer overflow */
7206|      if (newSize > (size_t)(-1) / sizeof(NAMED *)) {
7207|        return NULL;
7208|      }
7209|
7210|      size_t tsize = newSize * sizeof(NAMED *);
7211|      NAMED **newV = table->mem->malloc_fcn(tsize);
7212|      if (! newV)
7213|        return NULL;
7214|      memset(newV, 0, tsize);
7215|      for (i = 0; i < table->size; i++)
7216|        if (table->v[i]) {
7217|          unsigned long newHash = hash(parser, table->v[i]->name);
7218|          size_t j = newHash & newMask;
7219|          step = 0;
7220|          while (newV[j]) {
7221|            if (! step)
7222|              step = PROBE_STEP(newHash, newMask, newPower);
7223|            j < step ? (j += newSize - step) : (j -= step);
7224|          }
7225|          newV[j] = table->v[i];
7226|        }
7227|      table->mem->free_fcn(table->v);
7228|      table->v = newV;
7229|      table->power = newPower;
7230|      table->size = newSize;
7231|      i = h & newMask;
7232|      step = 0;
7233|      while (table->v[i]) {
7234|        if (! step)
7235|          step = PROBE_STEP(h, newMask, newPower);
7236|        i < step ? (i += newSize - step) : (i -= step);
7237|      }
7238|    }
7239|  }
7240|  table->v[i] = table->mem->malloc_fcn(createSize);
7241|  if (! table->v[i])
7242|    return NULL;
7243|  memset(table->v[i], 0, createSize);
7244|  table->v[i]->name = name;
7245|  (table->used)++;
7246|  return table->v[i];
7247|}
