7411|static size_t
7412|poolBytesToAllocateFor(int blockSize) {
7413|  /* Unprotected math would be:
7414|  ** return offsetof(BLOCK, s) + blockSize * sizeof(XML_Char);
7415|  **
7416|  ** Detect overflow, avoiding _signed_ overflow undefined behavior
7417|  ** For a + b * c we check b * c in isolation first, so that addition of a
7418|  ** on top has no chance of making us accept a small non-negative number
7419|  */
7420|  const size_t stretch = sizeof(XML_Char); /* can be 4 bytes */
7421|
7422|  if (blockSize <= 0)
7423|    return 0;
7424|
7425|  if (blockSize > (int)(INT_MAX / stretch))
7426|    return 0;
7427|
7428|  {
7429|    const int stretchedBlockSize = blockSize * (int)stretch;
7430|    const int bytesToAllocate
7431|        = (int)(offsetof(BLOCK, s) + (unsigned)stretchedBlockSize);
7432|    if (bytesToAllocate < 0)
7433|      return 0;
7434|
7435|    return (size_t)bytesToAllocate;
7436|  }
