7439|static XML_Bool FASTCALL
7440|poolGrow(STRING_POOL *pool) {
7441|  if (pool->freeBlocks) {
7442|    if (pool->start == 0) {
7443|      pool->blocks = pool->freeBlocks;
7444|      pool->freeBlocks = pool->freeBlocks->next;
7445|      pool->blocks->next = NULL;
7446|      pool->start = pool->blocks->s;
7447|      pool->end = pool->start + pool->blocks->size;
7448|      pool->ptr = pool->start;
7449|      return XML_TRUE;
7450|    }
7451|    if (pool->end - pool->start < pool->freeBlocks->size) {
7452|      BLOCK *tem = pool->freeBlocks->next;
7453|      pool->freeBlocks->next = pool->blocks;
7454|      pool->blocks = pool->freeBlocks;
7455|      pool->freeBlocks = tem;
7456|      memcpy(pool->blocks->s, pool->start,
7457|             (pool->end - pool->start) * sizeof(XML_Char));
7458|      pool->ptr = pool->blocks->s + (pool->ptr - pool->start);
7459|      pool->start = pool->blocks->s;
7460|      pool->end = pool->start + pool->blocks->size;
7461|      return XML_TRUE;
7462|    }
7463|  }
7464|  if (pool->blocks && pool->start == pool->blocks->s) {
7465|    BLOCK *temp;
7466|    int blockSize = (int)((unsigned)(pool->end - pool->start) * 2U);
7467|    size_t bytesToAllocate;
7468|
7469|    /* NOTE: Needs to be calculated prior to calling `realloc`
7470|             to avoid dangling pointers: */
7471|    const ptrdiff_t offsetInsideBlock = pool->ptr - pool->start;
7472|
7473|    if (blockSize < 0) {
7474|      /* This condition traps a situation where either more than
7475|       * INT_MAX/2 bytes have already been allocated.  This isn't
7476|       * readily testable, since it is unlikely that an average
7477|       * machine will have that much memory, so we exclude it from the
7478|       * coverage statistics.
7479|       */
7480|      return XML_FALSE; /* LCOV_EXCL_LINE */
7481|    }
7482|
7483|    bytesToAllocate = poolBytesToAllocateFor(blockSize);
7484|    if (bytesToAllocate == 0)
7485|      return XML_FALSE;
7486|
7487|    temp = (BLOCK *)pool->mem->realloc_fcn(pool->blocks,
7488|                                           (unsigned)bytesToAllocate);
7489|    if (temp == NULL)
7490|      return XML_FALSE;
7491|    pool->blocks = temp;
7492|    pool->blocks->size = blockSize;
7493|    pool->ptr = pool->blocks->s + offsetInsideBlock;
7494|    pool->start = pool->blocks->s;
7495|    pool->end = pool->start + blockSize;
7496|  } else {
7497|    BLOCK *tem;
7498|    int blockSize = (int)(pool->end - pool->start);
7499|    size_t bytesToAllocate;
7500|
7501|    if (blockSize < 0) {
7502|      /* This condition traps a situation where either more than
7503|       * INT_MAX bytes have already been allocated (which is prevented
7504|       * by various pieces of program logic, not least this one, never
7505|       * mind the unlikelihood of actually having that much memory) or
7506|       * the pool control fields have been corrupted (which could
7507|       * conceivably happen in an extremely buggy user handler
7508|       * function).  Either way it isn't readily testable, so we
7509|       * exclude it from the coverage statistics.
7510|       */
7511|      return XML_FALSE; /* LCOV_EXCL_LINE */
7512|    }
7513|
7514|    if (blockSize < INIT_BLOCK_SIZE)
7515|      blockSize = INIT_BLOCK_SIZE;
7516|    else {
7517|      /* Detect overflow, avoiding _signed_ overflow undefined behavior */
7518|      if ((int)((unsigned)blockSize * 2U) < 0) {
7519|        return XML_FALSE;
7520|      }
7521|      blockSize *= 2;
7522|    }
7523|
7524|    bytesToAllocate = poolBytesToAllocateFor(blockSize);
7525|    if (bytesToAllocate == 0)
7526|      return XML_FALSE;
7527|
7528|    tem = pool->mem->malloc_fcn(bytesToAllocate);
7529|    if (! tem)
7530|      return XML_FALSE;
7531|    tem->size = blockSize;
7532|    tem->next = pool->blocks;
7533|    pool->blocks = tem;
7534|    if (pool->ptr != pool->start)
7535|      memcpy(tem->s, pool->start, (pool->ptr - pool->start) * sizeof(XML_Char));
7536|    pool->ptr = tem->s + (pool->ptr - pool->start);
7537|    pool->start = tem->s;
7538|    pool->end = tem->s + blockSize;
7539|  }
7540|  return XML_TRUE;
