7604|static XML_Content *
7605|build_model(XML_Parser parser) {
7606|  /* Function build_model transforms the existing parser->m_dtd->scaffold
7607|   * array of CONTENT_SCAFFOLD tree nodes into a new array of
7608|   * XML_Content tree nodes followed by a gapless list of zero-terminated
7609|   * strings. */
7610|  DTD *const dtd = parser->m_dtd; /* save one level of indirection */
7611|  XML_Content *ret;
7612|  XML_Char *str; /* the current string writing location */
7613|
7614|  /* Detect and prevent integer overflow.
7615|   * The preprocessor guard addresses the "always false" warning
7616|   * from -Wtype-limits on platforms where
7617|   * sizeof(unsigned int) < sizeof(size_t), e.g. on x86_64. */
7618|#if UINT_MAX >= SIZE_MAX
7619|  if (dtd->scaffCount > (size_t)(-1) / sizeof(XML_Content)) {
7620|    return NULL;
7621|  }
7622|  if (dtd->contentStringLen > (size_t)(-1) / sizeof(XML_Char)) {
7623|    return NULL;
7624|  }
7625|#endif
7626|  if (dtd->scaffCount * sizeof(XML_Content)
7627|      > (size_t)(-1) - dtd->contentStringLen * sizeof(XML_Char)) {
7628|    return NULL;
7629|  }
7630|
7631|  const size_t allocsize = (dtd->scaffCount * sizeof(XML_Content)
7632|                            + (dtd->contentStringLen * sizeof(XML_Char)));
7633|
7634|  ret = (XML_Content *)MALLOC(parser, allocsize);
7635|  if (! ret)
7636|    return NULL;
7637|
7638|  /* What follows is an iterative implementation (of what was previously done
7639|   * recursively in a dedicated function called "build_node".  The old recursive
7640|   * build_node could be forced into stack exhaustion from input as small as a
7641|   * few megabyte, and so that was a security issue.  Hence, a function call
7642|   * stack is avoided now by resolving recursion.)
7643|   *
7644|   * The iterative approach works as follows:
7645|   *
7646|   * - We have two writing pointers, both walking up the result array; one does
7647|   *   the work, the other creates "jobs" for its colleague to do, and leads
7648|   *   the way:
7649|   *
7650|   *   - The faster one, pointer jobDest, always leads and writes "what job
7651|   *     to do" by the other, once they reach that place in the
7652|   *     array: leader "jobDest" stores the source node array index (relative
7653|   *     to array dtd->scaffold) in field "numchildren".
7654|   *
7655|   *   - The slower one, pointer dest, looks at the value stored in the
7656|   *     "numchildren" field (which actually holds a source node array index
7657|   *     at that time) and puts the real data from dtd->scaffold in.
7658|   *
7659|   * - Before the loop starts, jobDest writes source array index 0
7660|   *   (where the root node is located) so that dest will have something to do
7661|   *   when it starts operation.
7662|   *
7663|   * - Whenever nodes with children are encountered, jobDest appends
7664|   *   them as new jobs, in order.  As a result, tree node siblings are
7665|   *   adjacent in the resulting array, for example:
7666|   *
7667|   *     [0] root, has two children
7668|   *       [1] first child of 0, has three children
7669|   *         [3] first child of 1, does not have children
7670|   *         [4] second child of 1, does not have children
7671|   *         [5] third child of 1, does not have children
7672|   *       [2] second child of 0, does not have children
7673|   *
7674|   *   Or (the same data) presented in flat array view:
7675|   *
7676|   *     [0] root, has two children
7677|   *
7678|   *     [1] first child of 0, has three children
7679|   *     [2] second child of 0, does not have children
7680|   *
7681|   *     [3] first child of 1, does not have children
7682|   *     [4] second child of 1, does not have children
7683|   *     [5] third child of 1, does not have children
7684|   *
7685|   * - The algorithm repeats until all target array indices have been processed.
7686|   */
7687|  XML_Content *dest = ret; /* tree node writing location, moves upwards */
7688|  XML_Content *const destLimit = &ret[dtd->scaffCount];
7689|  XML_Content *jobDest = ret; /* next free writing location in target array */
7690|  str = (XML_Char *)&ret[dtd->scaffCount];
7691|
7692|  /* Add the starting job, the root node (index 0) of the source tree  */
7693|  (jobDest++)->numchildren = 0;
7694|
7695|  for (; dest < destLimit; dest++) {
7696|    /* Retrieve source tree array index from job storage */
7697|    const int src_node = (int)dest->numchildren;
7698|
7699|    /* Convert item */
7700|    dest->type = dtd->scaffold[src_node].type;
7701|    dest->quant = dtd->scaffold[src_node].quant;
7702|    if (dest->type == XML_CTYPE_NAME) {
7703|      const XML_Char *src;
7704|      dest->name = str;
7705|      src = dtd->scaffold[src_node].name;
7706|      for (;;) {
7707|        *str++ = *src;
7708|        if (! *src)
7709|          break;
7710|        src++;
7711|      }
7712|      dest->numchildren = 0;
7713|      dest->children = NULL;
7714|    } else {
7715|      unsigned int i;
7716|      int cn;
7717|      dest->name = NULL;
7718|      dest->numchildren = dtd->scaffold[src_node].childcnt;
7719|      dest->children = jobDest;
7720|
7721|      /* Append scaffold indices of children to array */
7722|      for (i = 0, cn = dtd->scaffold[src_node].firstchild;
7723|           i < dest->numchildren; i++, cn = dtd->scaffold[cn].nextsib)
7724|        (jobDest++)->numchildren = (unsigned int)cn;
7725|    }
7726|  }
7727|
7728|  return ret;
7729|}
