7731|static ELEMENT_TYPE *
7732|getElementType(XML_Parser parser, const ENCODING *enc, const char *ptr,
7733|               const char *end) {
7734|  DTD *const dtd = parser->m_dtd; /* save one level of indirection */
7735|  const XML_Char *name = poolStoreString(&dtd->pool, enc, ptr, end);
7736|  ELEMENT_TYPE *ret;
7737|
7738|  if (! name)
7739|    return NULL;
7740|  ret = (ELEMENT_TYPE *)lookup(parser, &dtd->elementTypes, name,
7741|                               sizeof(ELEMENT_TYPE));
7742|  if (! ret)
7743|    return NULL;
7744|  if (ret->name != name)
7745|    poolDiscard(&dtd->pool);
7746|  else {
7747|    poolFinish(&dtd->pool);
7748|    if (! setElementTypePrefix(parser, ret))
7749|      return NULL;
7750|  }
7751|  return ret;
