7754|static XML_Char *
7755|copyString(const XML_Char *s, const XML_Memory_Handling_Suite *memsuite) {
7756|  size_t charsRequired = 0;
7757|  XML_Char *result;
7758|
7759|  /* First determine how long the string is */
7760|  while (s[charsRequired] != 0) {
7761|    charsRequired++;
7762|  }
7763|  /* Include the terminator */
7764|  charsRequired++;
7765|
7766|  /* Now allocate space for the copy */
7767|  result = memsuite->malloc_fcn(charsRequired * sizeof(XML_Char));
7768|  if (result == NULL)
7769|    return NULL;
7770|  /* Copy the original into place */
7771|  memcpy(result, s, charsRequired * sizeof(XML_Char));
7772|  return result;
7773|}
