7778|accountingGetCurrentAmplification(XML_Parser rootParser) {
7779|  const XmlBigCount countBytesOutput
7780|      = rootParser->m_accounting.countBytesDirect
7781|        + rootParser->m_accounting.countBytesIndirect;
7782|  const float amplificationFactor
7783|      = rootParser->m_accounting.countBytesDirect
7784|            ? (countBytesOutput
7785|               / (float)(rootParser->m_accounting.countBytesDirect))
7786|            : 1.0f;
7787|  assert(! rootParser->m_parentParser);
7788|  return amplificationFactor;
