7815|static void
7816|accountingReportDiff(XML_Parser rootParser,
7817|                     unsigned int levelsAwayFromRootParser, const char *before,
7818|                     const char *after, ptrdiff_t bytesMore, int source_line,
7819|                     enum XML_Account account) {
7820|  assert(! rootParser->m_parentParser);
7821|
7822|  fprintf(stderr,
7823|          " (+" EXPAT_FMT_PTRDIFF_T("6") " bytes %s|%d, xmlparse.c:%d) %*s\"",
7824|          bytesMore, (account == XML_ACCOUNT_DIRECT) ? "DIR" : "EXP",
7825|          levelsAwayFromRootParser, source_line, 10, "");
7826|
7827|  const char ellipis[] = "[..]";
7828|  const size_t ellipsisLength = sizeof(ellipis) /* because compile-time */ - 1;
7829|  const unsigned int contextLength = 10;
7830|
7831|  /* Note: Performance is of no concern here */
7832|  const char *walker = before;
7833|  if ((rootParser->m_accounting.debugLevel >= 3u)
7834|      || (after - before)
7835|             <= (ptrdiff_t)(contextLength + ellipsisLength + contextLength)) {
7836|    for (; walker < after; walker++) {
7837|      fprintf(stderr, "%s", unsignedCharToPrintable(walker[0]));
7838|    }
7839|  } else {
7840|    for (; walker < before + contextLength; walker++) {
7841|      fprintf(stderr, "%s", unsignedCharToPrintable(walker[0]));
7842|    }
7843|    fprintf(stderr, ellipis);
7844|    walker = after - contextLength;
7845|    for (; walker < after; walker++) {
7846|      fprintf(stderr, "%s", unsignedCharToPrintable(walker[0]));
7847|    }
7848|  }
7849|  fprintf(stderr, "\"\n");
7850|}
