7852|static XML_Bool
7853|accountingDiffTolerated(XML_Parser originParser, int tok, const char *before,
7854|                        const char *after, int source_line,
7855|                        enum XML_Account account) {
7856|  /* Note: We need to check the token type *first* to be sure that
7857|   *       we can even access variable <after>, safely.
7858|   *       E.g. for XML_TOK_NONE <after> may hold an invalid pointer. */
7859|  switch (tok) {
7860|  case XML_TOK_INVALID:
7861|  case XML_TOK_PARTIAL:
7862|  case XML_TOK_PARTIAL_CHAR:
7863|  case XML_TOK_NONE:
7864|    return XML_TRUE;
7865|  }
7866|
7867|  if (account == XML_ACCOUNT_NONE)
7868|    return XML_TRUE; /* because these bytes have been accounted for, already */
7869|
7870|  unsigned int levelsAwayFromRootParser;
7871|  const XML_Parser rootParser
7872|      = getRootParserOf(originParser, &levelsAwayFromRootParser);
7873|  assert(! rootParser->m_parentParser);
7874|
7875|  const int isDirect
7876|      = (account == XML_ACCOUNT_DIRECT) && (originParser == rootParser);
7877|  const ptrdiff_t bytesMore = after - before;
7878|
7879|  XmlBigCount *const additionTarget
7880|      = isDirect ? &rootParser->m_accounting.countBytesDirect
7881|                 : &rootParser->m_accounting.countBytesIndirect;
7882|
7883|  /* Detect and avoid integer overflow */
7884|  if (*additionTarget > (XmlBigCount)(-1) - (XmlBigCount)bytesMore)
7885|    return XML_FALSE;
7886|  *additionTarget += bytesMore;
7887|
7888|  const XmlBigCount countBytesOutput
7889|      = rootParser->m_accounting.countBytesDirect
7890|        + rootParser->m_accounting.countBytesIndirect;
7891|  const float amplificationFactor
7892|      = accountingGetCurrentAmplification(rootParser);
7893|  const XML_Bool tolerated
7894|      = (countBytesOutput < rootParser->m_accounting.activationThresholdBytes)
7895|        || (amplificationFactor
7896|            <= rootParser->m_accounting.maximumAmplificationFactor);
7897|
7898|  if (rootParser->m_accounting.debugLevel >= 2u) {
7899|    accountingReportStats(rootParser, "");
7900|    accountingReportDiff(rootParser, levelsAwayFromRootParser, before, after,
7901|                         bytesMore, source_line, account);
7902|  }
7903|
7904|  return tolerated;
7905|}
