7969|static XML_Parser
7970|getRootParserOf(XML_Parser parser, unsigned int *outLevelDiff) {
7971|  XML_Parser rootParser = parser;
7972|  unsigned int stepsTakenUpwards = 0;
7973|  while (rootParser->m_parentParser) {
7974|    rootParser = rootParser->m_parentParser;
7975|    stepsTakenUpwards++;
7976|  }
7977|  assert(! rootParser->m_parentParser);
7978|  if (outLevelDiff != NULL) {
7979|    *outLevelDiff = stepsTakenUpwards;
7980|  }
7981|  return rootParser;
